content.content:
=== config_with_getenv.hcl ===
env "test" {
  url = "sqlite://test.db"
  dev = "sqlite://dev?mode=memory"
  custom_value = getenv("ATLAS_TEST_VAR")
  empty_value = getenv("ATLAS_NONEXISTENT_VAR")
}
=== config_with_locals.hcl ===
locals {
  common_dev = "sqlite://dev?mode=memory"
  env_name = atlas.env
}

env "local" {
  url = "sqlite://local.db"
  dev = local.common_dev
  env_field = local.env_name
}
=== config_with_vars.hcl ===
variable "db_name" {
  type = string
  default = "default.db"
}

variable "schema_name" {
  type = string
  default = "main"
}

env "test" {
  url = "sqlite://${var.db_name}"
  dev = "sqlite://dev?mode=memory"
  schemas = [var.schema_name]
}
=== formatted.hcl ===
schema "test" {
  charset = "utf8mb4"
  collate = "utf8mb4_general_ci"
}

table "users" {
  schema = schema.test
  column "id" {
    type = int
    null = false
  }
  column "name" {
    type = varchar(255)
  }
  primary_key {
    columns = [column.id]
  }
}

table "posts" {
  schema = schema.test
  column "id" {
    type = int
  }
  column "user_id" {
    type = int
  }
}
