    default = sql("CURRENT_TIMESTAMP")
  }
  column "data" {
    null = true
    type = blob
  }
  column "score" {
    null = true
    type = real
  }
  column "meta" {
    null = true
    type = json
  }
  column "full_name" {
    null = true
    type = text
    as {
      expr = "(name || ' x')"
      type = STORED
    }
  }
  column "virt" {
    null = true
    type = text
    as {
      expr = "(name || 'v')"
      type = VIRTUAL
    }
  }
  primary_key {
    columns = [column.id]
  }
  index "sqlite_autoindex_users_1" {
    unique  = true
    columns = [column.email]
  }
  index "idx_users_name" {
    columns = [column.name]
  }
  index "idx_users_email_lower" {
    unique = true
    where  = "age > 5"
    on {
      expr = "lower(email)"
    }
  }
  index "idx_desc" {
    on {
      desc   = true
      column = column.name
    }
    on {
      column = column.age
    }
  }
  check {
    expr = "(age >= 0)"
  }
}
table "posts" {
  schema = schema.main
  column "id" {
    null = false
    type = integer
  }
  column "user_id" {
    null = false
    type = integer
  }
  column "title" {
    null = true
    type = text
  }
  primary_key {
    columns = [column.id]
  }
  foreign_key "0" {
    columns     = [column.user_id]
    ref_columns = [table.users.column.id]
    on_update   = NO_ACTION
    on_delete   = CASCADE
  }
}
schema "main" {
}
