input.command:
source /tmp/explore/hcl/r.sh; cd /tmp/explore/hcl
mkdir -p blocks
# Test each top-level block type
for b in view enum function trigger materialized index composite sequence domain procedure policy type extension aggregate event; do
  echo "########## BLOCK: $b"
  case $b in
    view) printf 'schema "main" {
}
view "v" {
  schema = schema.main
  as = "SELECT 1 AS a"
  column "a" {
    type = int
  }
}
' > blocks/$b.hcl;;
    enum) printf 'schema "main" {
}
enum "e" {
  schema = schema.main
  values = ["a","b"]
}
' > blocks/$b.hcl;;
    function) printf 'schema "main" {
}
function "f" {
  schema = schema.main
  lang = SQL
  return = int
  as = "SELECT 1"
}
' > blocks/$b.hcl;;
    trigger) printf 'schema "main" {
}
table "t" {
  schema = schema.main
  column "c" { type = int }
}
trigger "tr" {
  on = table.t
  after { insert = true }
  as = "SELECT 1"
}
' > blocks/$b.hcl;;
    materialized) printf 'schema "main" {
}
materialized "m" {
  schema = schema.main
  as = "SELECT 1 AS a"
}
' > blocks/$b.hcl;;
    index) printf 'schema "main" {
}
index "i" {
  schema = schema.main
}
' > blocks/$b.hcl;;
    composite) printf 'schema "main" {
}
composite "c" {
  schema = schema.main
  field "f" { type = int }
}
' > blocks/$b.hcl;;
    sequence) printf 'schema "main" {
}
sequence "s" {
  schema = schema.main
}
' > blocks/$b.hcl;;
    domain) printf 'schema "main" {
}
domain "d" {
  schema = schema.main
  type = int
}
' > blocks/$b.hcl;;
    *) printf 'schema "main" {
}
%s "x" {
  schema = schema.main
}
' "$b" > blocks/$b.hcl;;
  esac
  run schema diff --from "file://empty.hcl" --to "file://blocks/$b.hcl" --dev-url "sqlite://dev?mode=memory"
done

