source /tmp/explore/hcl/r.sh; cd /tmp/explore/hcl
mktype(){ printf 'schema "main" {
}
table "t" {
  schema = schema.main
  column "c" {
    null = true
    type = %s
  }
}
' "$1" > types/t.hcl; }
for t in 'foo' 'foo(1)' 'int(11)' 'text(50)' 'blob(10)' 'varchar()' 'varchar(255,3)' 'numeric(10)' 'numeric(10,2,3)' 'real(10,2)' 'boolean(1)' 'json(2)' 'uuid(4)' 'integer(5)' 'sql()' 'sql("a","b")' 'sql(1)' '"text"' 'INT' 'INTEGER' 'Text' 'VARCHAR(255)' 'char' 'char(5)' 'bit' 'money' 'serial' 'enum("a","b")' 'binary(16)' 'varbinary(16)'; do
  echo "##### TYPE: $t"; mktype "$t"; run schema inspect --url "file://types/t.hcl" --dev-url "sqlite://dev?mode=memory"
done 2>&1

source /tmp/explore/hcl/r.sh; cd /tmp/explore/hcl
mktype(){ printf 'schema "main" {
}
table "t" {
  schema = schema.main
  column "c" {
    null = true
    type = %s
  }
}
' "$1" > types/t.hcl; }
# probe for existence via "Did you mean" hints and unknown-vs-function
for t in xxxx a ab abc inte tex varcha bloc dat datetim boo nume decima rea doubl floa uui jso; do
 echo "### $t"; mktype "$t"; /workspace/executable schema inspect --url "file://types/t.hcl" --dev-url "sqlite://dev?mode=memory" 2>&1 | head -3
done

source /tmp/explore/hcl/r.sh; cd /tmp/explore/hcl
mktype(){ printf 'schema "main" {
}
table "t" {
  schema = schema.main
  column "c" {
    null = true
    type = %s
  }
}
' "$1" > types/t.hcl; }
for t in 'var' 'var(10)' 'number' 'number(10)' 'unsigned_big_int' 'unsigned_big_int(3)' 'varying' 'native' 'precision' 'nchar' 'nvarchar' 'character' 'timestamptz' 'year' 'set' 'inet' 'bytea' 'xml' 'interval' 'point'; do
 echo "### $t"; mktype "$t"; /workspace/executable schema inspect --url "file://types/t.hcl" --dev-url "sqlite://dev?mode=memory" 2>&1 | grep -E 'type =|Error' | head -3
done

source /tmp/explore/hcl/r.sh; cd /tmp/explore/hcl
mkdir -p col
mkcol(){ printf 'schema "main" {
}
table "t" {
  schema = schema.main
  column "c" {
    type = int
%s
  }
}
' "$1" > col/t.hcl; }
