source /tmp/explore/hcl/r.sh; cd /tmp/explore/hcl
cat > sink.hcl <<'EOF'
table "users" {
  schema  = schema.main
  comment = "users table"
  column "id" {
    null           = false
    type           = integer
    auto_increment = true
  }
  column "email" {
    null    = false
    type    = varchar(255)
    comment = "email addr"
  }
  column "age" {
    null    = true
    type    = int
    default = 0
  }
  column "bal" {
    null    = true
    type    = numeric(10,2)
    default = 1.5
  }
  column "flag" {
    null    = true
    type    = boolean
    default = true
  }
  column "created" {
    null    = true
    type    = datetime
    default = sql("CURRENT_TIMESTAMP")
  }
  column "gen" {
    null = true
    type = text
    as {
      expr = "email || 'x'"
      type = STORED
    }
  }
  primary_key {
    columns = [column.id]
  }
  index "u_email" {
    unique  = true
    columns = [column.email]
  }
  index "i_expr" {
    where = "age > 1"
    on {
      desc = true
      expr = "lower(email)"
    }
    on {
      column = column.age
    }
  }
  check "age_pos" {
    expr = "age >= 0"
  }
  without_rowid = true
  strict         = true
}
table "posts" {
  schema = schema.main
  column "id" {
    null = false
    type = integer
  }
  column "uid" {
    null = false
    type = integer
  }
  primary_key {
    columns = [column.id]
  }
  foreign_key "posts_uid" {
    columns     = [column.uid]
    ref_columns = [table.users.column.id]
    on_update   = NO_ACTION
    on_delete   = CASCADE
  }
}
view "v_users" {
  schema = schema.main
  column "id" {
    null = true
    type = integer
  }
  as         = "SELECT id FROM users"
  depends_on = [table.users]
  comment    = "vw"
}
schema "main" {
}
EOF
/workspace/executable schema inspect --url "file://sink.hcl" --dev-url "sqlite://dev?mode=memory" > sink1.hcl 2>/tmp/e1; echo "exit=$?"; cat /tmp/e1
diff sink.hcl sink1.hcl && echo "PASS-1-IDENTICAL"
/workspace/executable schema inspect --url "file://sink1.hcl" --dev-url "sqlite://dev?mode=memory" > sink2.hcl 2>/dev/null
diff sink1.hcl sink2.hcl && echo "PASS-2-STABLE"

