$ atlas schema apply --url sqlite://sink.db --to file://sink1.hcl --dev-url sqlite://dev?mode=memory --auto-approve
exit=1
--stdout--
-- Planned Changes:
-- Create "users" table
CREATE TABLE `users` (
  `id` integer NOT NULL PRIMARY KEY AUTOINCREMENT,
  `email` varchar NOT NULL,
  `age` int NULL DEFAULT 0,
  `bal` numeric NULL DEFAULT 1.5,
  `flag` boolean NULL DEFAULT true,
  `created` datetime NULL DEFAULT (CURRENT_TIMESTAMP),
  `gen` text NULL AS (email || 'x') STORED,
  CONSTRAINT `age_pos` CHECK (age >= 0)
) WITHOUT ROWID, STRICT;
-- Create index "u_email" to table: "users"
CREATE UNIQUE INDEX `u_email` ON `users` (`email`);
-- Create index "i_expr" to table: "users"
CREATE INDEX `i_expr` ON `users` ((lower(email)) DESC, `age`) WHERE age > 1;
-- Create "posts" table
CREATE TABLE `posts` (
  `id` integer NOT NULL,
  `uid` integer NOT NULL,
  PRIMARY KEY (`id`),
  CONSTRAINT `posts_uid` FOREIGN KEY (`uid`) REFERENCES `users` (`id`) ON UPDATE NO ACTION ON DELETE CASCADE
);
